# --- 세 가지로 같은 것을 적는다 ---

$ cat ThreeWays.java
// ① 익명 클래스
new Thread(new Runnable() {
    @Override public void run() { log.info("일한다"); }
}, "anon").start();

// ② 람다
new Thread(() -> log.info("일한다"), "lambda").start();

// ③ 메서드 참조
new Thread(ThreeWays::work, "ref").start();

$ java -cp out:libs/* ThreeWays
00:12:02.104 [anon        ] INFO  ThreeWays - 일한다
00:12:02.108 [lambda      ] INFO  ThreeWays - 일한다
00:12:02.108 [ref         ] INFO  ThreeWays - 일한다

$ grep -c '' ThreeWaysAnon.java ThreeWaysLambda.java
ThreeWaysAnon.java:11
ThreeWaysLambda.java:7

#   같은 일을 4줄 짧게 적었다


# --- 만들어진 클래스가 다르다 ---

$ javac -d out ThreeWays.java && ls out/ | grep ThreeWays
ThreeWays$1.class
ThreeWays.class

$ javap -p out/ThreeWays.class | grep lambda
  private static void lambda$main$0();

$ javap -c -p out/ThreeWays.class | grep -A2 'invokedynamic' | head -3
      18: invokedynamic #29,  0   // InvokeDynamic #0:run:()Ljava/lang/Runnable;

#   익명 클래스는 .class 파일이 생긴다
#   람다는 안 생기고 invokedynamic 이 쓰인다


# --- this 가 다르다 ---

$ cat WhoIsThis.java
public class WhoIsThis {
    void anon() {
        new Thread(new Runnable() {
            @Override public void run() { log.info("익명 this {}", this.getClass().getName()); }
        }).start();
    }
    void lambda() {
        new Thread(() -> log.info("람다 this {}", this.getClass().getName())).start();
    }
}

$ java -cp out:libs/* WhoIsThis
00:12:08.204 [Thread-0    ] INFO  WhoIsThis - 익명 this WhoIsThis$1
00:12:08.208 [Thread-1    ] INFO  WhoIsThis - 람다 this WhoIsThis

#   람다의 this 는 바깥 객체다
#   6.3절에서 락을 걸 때 이 차이가 나온다


# --- 지역 변수는 복사된다 ---

$ cat CaptureLocal.java | grep -A5 'void run'
void run() {
    int n = 10;
    new Thread(() -> log.info("람다가 본 n = {}", n), "w-0").start();
    n = 20;                                  // 컴파일 오류
}

$ javac -d out CaptureLocal.java 2>&1 | head -3
CaptureLocal.java:5: error: local variables referenced from a lambda expression
  must be final or effectively final
        n = 20;
        ^

#   바꾸지 못하게 막는다


# --- 왜 막나 ---

$ cat WhyFinal.java | grep -A5 'void run'
void run() {
    int n = 10;
    Runnable r = () -> log.info("n = {}", n);
    // n 이 바뀔 수 있다면 이 람다가 볼 값이 언제 정해지나?
    new Thread(r).start();
}

$ javap -p out/WhyFinal.class | grep lambda
  private static void lambda$run$0(int);

#   값을 인자로 받아 간다
#   복사본이라 원본이 바뀌어도 안 보인다


# --- 반복 변수는 못 쓴다 ---

$ cat LoopVar.java | grep -A3 'for (int i'
for (int i = 0; i < 3; i++)
    new Thread(() -> log.info("i = {}", i)).start();

$ javac -d out LoopVar.java 2>&1 | head -2
LoopVar.java:6: error: local variables referenced from a lambda expression
  must be final or effectively final

$ cat LoopVarFixed.java | grep -A4 'for (int i'
for (int i = 0; i < 3; i++) {
    final int idx = i;                       // 매번 새 변수
    new Thread(() -> log.info("idx = {}", idx), "w-" + i).start();
}

$ java -cp out:libs/* LoopVarFixed 2>/dev/null | sort
00:12:16.104 [w-0         ] INFO  LoopVarFixed - idx = 0
00:12:16.108 [w-1         ] INFO  LoopVarFixed - idx = 1
00:12:16.108 [w-2         ] INFO  LoopVarFixed - idx = 2

$ cat ForEachOk.java | grep -A2 'for (int idx'
for (int idx : new int[]{0,1,2})
    new Thread(() -> log.info("idx = {}", idx)).start();

$ javac -d out ForEachOk.java && echo '향상된 for 는 된다'
향상된 for 는 된다

#   향상된 for 는 매 회전마다 새 변수다


# --- 필드는 안 복사된다 ---

$ cat CaptureField.java
public class CaptureField {
    int count = 0;

    void run() throws Exception {
        Thread[] ts = new Thread[4];
        for (int i = 0; i < 4; i++) {
            ts[i] = new Thread(() -> { for (int j = 0; j < 100000; j++) count++; }, "w-" + i);
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        log.info("기대 400000 실제 {}", count);
    }
}

$ javac -d out CaptureField.java && echo '컴파일 통과'
컴파일 통과

$ ./run.sh CaptureField 20 '[0-9]+$' | head -3
   2 400000
   1 314204
   1 288412

$ ./run.sh CaptureField 20 '[0-9]+$' | awk '$2==400000 {print "맞음", $1"/20"}'
맞음 2/20

#   지역 변수는 막았는데 필드는 안 막는다
#   1.4절과 같은 결과다


# --- 배열로 우회하면 ---

$ cat ArrayEscape.java | grep -A4 'void run'
void run() throws Exception {
    int[] count = new int[1];                // 참조는 final 이다
    for (int i = 0; i < 4; i++)
        new Thread(() -> { for (int j = 0; j < 100000; j++) count[0]++; }).start();
}

$ javac -d out ArrayEscape.java && echo '컴파일 통과'
컴파일 통과

$ ./run.sh ArrayEscape 20 '[0-9]+$' | awk '$2==400000 {print "맞음", $1"/20"}'
맞음 1/20

#   컴파일러가 막아 주던 걸 뚫었다
#   "final 이어야 한다" 가 안전을 보장한 게 아니었다


# --- 각자 칸을 쓰면 ---

$ cat ArraySeparate.java | grep -A4 'void run'
int[] result = new int[4];
for (int i = 0; i < 4; i++) {
    final int idx = i;
    ts[i] = new Thread(() -> { for (int j = 0; j < 100000; j++) result[idx]++; });
}

$ ./run.sh ArraySeparate 20 '합 [0-9]+' | head -2
  20 합 400000

#   같은 배열인데 칸이 달라 안 겹친다
#   3.4절의 그 방법이다


# --- 바깥 객체를 붙잡는다 ---

$ cat HoldsOuter.java | grep -A6 'static Runnable make'
static Runnable make() {
    Big big = new Big();                     // 100MB 짜리
    return () -> log.info("{}", big.id);     // big 을 데려간다
}

$ java -Xmx512m -cp out:libs/* HoldsOuter --keep 4
00:12:28.104 [main] INFO  HoldsOuter - 람다 4개 들고 있음
$ jcmd $(pgrep -f HoldsOuter) GC.heap_info | head -1
 garbage-first heap   total 524288K, used 412048K

$ java -Xmx512m -cp out:libs/* HoldsOuter --keep 6
00:12:32.204 [main] ERROR HoldsOuter - java.lang.OutOfMemoryError: Java heap space

#   람다가 살아 있으면 캡처한 것도 산다
#   11.2절에서 큐에 쌓인 작업이 이러면 문제가 된다


# --- 필요한 것만 데려간다 ---

$ cat HoldsOnlyId.java | grep -A4 'static Runnable make'
static Runnable make() {
    Big big = new Big();
    final long id = big.id;                  // 값만 뽑는다
    return () -> log.info("{}", id);
}

$ java -Xmx512m -cp out:libs/* HoldsOnlyId --keep 20
00:12:36.104 [main] INFO  HoldsOnlyId - 람다 20개 들고 있음
$ jcmd $(pgrep -f HoldsOnlyId) GC.heap_info | head -1
 garbage-first heap   total 524288K, used 12408K

$ python3 -c "print('412MB 가 12MB 가 됐다')"
412MB 가 12MB 가 됐다


# --- 만드는 값 ---

$ java -cp out:libs/* LambdaBench --count 1000000 --mode anon
익명 클래스 100만개  84ms
$ java -cp out:libs/* LambdaBench --count 1000000 --mode lambda
람다 100만개         41ms
$ java -cp out:libs/* LambdaBench --count 1000000 --mode lambda-capture
캡처하는 람다 100만개 118ms

#   캡처가 없으면 람다는 하나만 만들어 재사용한다
#   캡처하면 매번 새로 만든다

$ java -cp out:libs/* LambdaIdentity
00:12:42.104 [main] INFO  LambdaIdentity - 캡처 없는 람다 두 개 같은 객체? true
00:12:42.104 [main] INFO  LambdaIdentity - 캡처하는 람다 두 개 같은 객체? false


